dispersionBeginReceipt:
function dispersionBeginReceipt(p,amount,date,reference,method){
  if(!Number.isFinite(Number(amount))||Number(amount)<=0||Math.abs(Number(amount)-roundToCents(amount))>0.0000001||!/^\d{4}-\d{2}-\d{2}$/.test(String(date||''))||dispersionDateOnly(date)!==date||!String(reference||'').trim()||!String(method||'').trim()){toast('Captura monto recibido con máximo dos decimales, fecha válida, método y referencia real del pago.');return null;}
  if((db.patients||[]).some(credit=>(credit.payments||[]).some(m=>String(m.reference||'').trim().toLowerCase()===String(reference).trim().toLowerCase()&&m.paymentType!=='reversal'&&!(credit.payments||[]).some(r=>r.reversalOf&&r.reversalOf===m.receiptId)))){toast('Esta referencia ya tiene un recibo registrado. Revisa el historial antes de aplicar otro pago.');return null;}
  try{if(localStorage.getItem(DEMO_STORAGE_KEY)!==dispersionLedgerStorageVersion){toast('Los datos cambiaron en otra pestaña. Recarga antes de registrar el pago.');return null;}}
  catch(error){toast('No se pudo verificar el almacenamiento. El pago no se aplicó.');return null;}
  return {patient:p,before:JSON.parse(JSON.stringify(p)),dbBefore:JSON.stringify(db),storageBefore:dispersionLedgerStorageVersion,receiptId:dispersionReceiptId(),amount:roundToCents(amount),date,reference:String(reference).trim(),method};
}

dispersionCommitReceipt:
function dispersionCommitReceipt(tx){
  const p=tx.patient,m=p.payments?.[p.payments.length-1];
  try{
    if(!m||p.payments.length!==(tx.before.payments||[]).length+1)throw new Error('Missing receipt');
    if(localStorage.getItem(DEMO_STORAGE_KEY)!==tx.storageBefore)throw new Error('Concurrent state change');
    const unapplied=roundToCents(dispersionNumber(m.unappliedAmount??m.excessAmount,0));
    const applied=roundToCents(dispersionNumber(m.totalApplied,tx.amount-unapplied));
    if(applied<=0||unapplied<0||Math.abs(tx.amount-applied-unapplied)>0.011)throw new Error('Receipt does not reconcile');
    Object.assign(m,{receiptId:tx.receiptId,amountReceived:tx.amount,totalApplied:applied,unappliedAmount:unapplied,reference:tx.reference,actor:session?.email||session?.name,allocations:[]});
    for(const row of p.paymentSchedule||[]){
      const old=(tx.before.paymentSchedule||[]).find(x=>x.id===row.id)||{};
      for(const d of dispersionConceptDefs()){
        const amount=roundToCents(dispersionNumber(row[d.paid],0)-dispersionNumber(old[d.paid],0));
        if(amount>0)m.allocations.push({rowId:row.id,concept:d.key,amount});
      }
    }
    if(m.paymentType==='extension')m.allocations=[['interes',m.interestCovered],['ivaInteres',m.ivaInterestCovered],['moratorio',m.moratoryCovered],['ivaMoratorio',m.ivaMoratoryCovered],['extensionFee',m.extensionFee],['extensionFeeVat',m.extensionFeeVat]].filter(x=>x[1]>0).map(([concept,amount])=>({rowId:m.rowId,concept,amount}));
    if(m.paymentType==='capital_prepay'&&m.appliedToCapital>0)m.allocations.push({concept:'capital_prepay',amount:roundToCents(m.appliedToCapital)});
    if(m.paymentType==='commission_upfront'){const terms=dispersionTerms(p);const tax=terms.openingFeeTaxVersion?roundToCents(applied*dispersionNumber(terms.openingFeeIvaAmount,0)/Math.max(terms.openingFeeAmount,0.01)):0;m.allocations=[{concept:'commission_upfront',amount:roundToCents(applied-tax)},...(tax>0?[{concept:'commission_upfront_iva',amount:tax}]:[])];}
    if(m.paymentType==='early_settlement')m.allocations=[['capital',m.capitalSettled],['interes',m.interestSettled],['ivaInteres',m.ivaInterestSettled],['moratorio',m.moratorySettled],['ivaMoratorio',m.ivaMoratorySettled],['commission',m.commissionsSettled]].filter(x=>x[1]>0).map(([concept,amount])=>({concept,amount:roundToCents(amount)}));
    if(Math.abs(roundToCents(m.allocations.reduce((sum,a)=>sum+a.amount,0))-applied)>0.001)throw new Error('Allocations do not reconcile');
    if(p.application)delete p.application.earlySettlementSimulation; delete p.earlySettlementSimulation;
    m.undoChanges=['paymentSchedule','application','offer','paymentCalendarSignature'].filter(k=>JSON.stringify(tx.before[k])!==JSON.stringify(p[k])).map(key=>({key,before:tx.before[key],after:JSON.parse(JSON.stringify(p[key]??null))}));
    db.__version=DEMO_VERSION;
    const serialized=JSON.stringify(db);
    localStorage.setItem(DEMO_STORAGE_KEY,serialized);
    dispersionLedgerStorageVersion=serialized;
    return true;
  }catch(error){dispersionRollbackReceipt(tx);toast('No se guardó el pago. No se modificaron saldos; revisa almacenamiento o recarga si otra pestaña cambió los datos.');return false;}
}

dispersionCanApplyEarlySettlement:
function dispersionCanApplyEarlySettlement(p,amount,date=dispersionDateOnly(new Date())){
  if(!p||dispersionIsCreditLiquidated(p))return {ok:false,message:'Este crédito ya fue liquidado anticipadamente. No se pueden aplicar nuevos pagos.'};
  if(!dispersionCanSimulateEarlySettlement(p))return {ok:false,message:'La liquidación anticipada requiere cumplir la fecha habilitada por la configuración vigente.'};
  const sim=dispersionLatestEarlySettlementSimulation(p);
  if(!sim||!(dispersionNumber(sim.totalToSettle??sim.total,0)>0))return {ok:false,message:'Primero calcula la simulación de liquidación.'};
  if(sim.calculationDate!==date||sim.balanceFingerprint!==dispersionSettlementFingerprint(p))return {ok:false,message:'La simulación cambió o venció. Recalcula con la fecha del pago y los saldos actuales.'};
  const total=roundToCents(dispersionNumber(sim.totalToSettle??sim.total,0));
  if(dispersionNumber(amount,0)<total)return {ok:false,message:'El monto recibido es menor al total para liquidar. No es posible cerrar el crédito.'};
  return {ok:true,total,sim,excess:Math.max(dispersionNumber(amount,0)-total,0)};
}

dispersionApplyEarlySettlement:
function dispersionApplyEarlySettlement(p,amount,date,reference,method){
  if(!requireCapability('patientActions'))return false;
  const validation=dispersionCanApplyEarlySettlement(p,amount,date);
  if(!validation.ok){toast(validation.message);return false;}
  const sim=validation.sim;
  const total=validation.total;
  const excess=validation.excess;
  const msg='¿Confirmas aplicar la liquidación anticipada y cerrar el crédito?';
  if(typeof confirm!=='function'||!confirm(msg))return false;
  const tx=dispersionBeginReceipt(p,amount,date,reference,method);if(!tx)return false;
  const rows=dispersionEnsureSchedule(p);
  rows.forEach(row=>{
    const status=String(row.status||'');
    if(['Pagado','Pagado anticipado','Reducida por prepago','Cancelado','Condonado'].includes(status))return;
    row.settlementApplied=true;
    row.settlementDate=date;
    row.reference=reference;
    row.method=method;
    const isFuture=['Programado','Parcial anticipado'].includes(status)||(status==='Ajustada por prepago'&&!dispersionIsAdjustedPrepayPayable(row,date));
    if(isFuture){
      row.status='Cancelada por liquidación';
      row.paymentType='early_settlement_cancellation';
      dispersionSetConceptsSettled(row,'cancelled');
    }else{
      row.status='Liquidado anticipadamente';
      row.paymentType='early_settlement';
      dispersionSetConceptsSettled(row,'covered');
      row.paymentDate=date;
    }
  });
  p.paymentSchedule=rows;
  p.application=p.application||{};
  p.application.financialStatus='liquidated_early';
  p.application.creditStatus='liquidated_early';
  p.application.earlySettlementApplied=true;
  p.application.earlySettlementAppliedAt=new Date().toISOString();
  p.application.earlySettlementSummary={
    date,
    amountReceived:amount,
    totalApplied:total,
    excessAmount:excess,
    capitalSettled:dispersionNumber(sim.capitalPending,0),
    interestSettled:dispersionNumber(sim.interestAccrued||sim.accruedOrdinaryInterest||0,0),
    ivaInterestSettled:dispersionNumber(sim.interestIvaAccrued||sim.ivaInterestPending||0,0),
    moratorySettled:dispersionNumber(sim.moratoryPending,0),
    ivaMoratorySettled:dispersionNumber(sim.moratoryIvaPending,0),
    commissionsSettled:dispersionNumber(sim.commissionsPending,0),
    reference,
    method,
    status:'Liquidado anticipadamente',
    simulation:sim
  };
  if(!Array.isArray(p.payments))p.payments=[];
  p.payments.push({paymentType:'early_settlement',movementLabel:'Liquidación anticipada aplicada',date,amountReceived:amount,totalApplied:total,excessAmount:excess,capitalSettled:p.application.earlySettlementSummary.capitalSettled,interestSettled:p.application.earlySettlementSummary.interestSettled,ivaInterestSettled:p.application.earlySettlementSummary.ivaInterestSettled,moratorySettled:p.application.earlySettlementSummary.moratorySettled,ivaMoratorySettled:p.application.earlySettlementSummary.ivaMoratorySettled,commissionsSettled:p.application.earlySettlementSummary.commissionsSettled,reference,method,createdAt:new Date().toISOString()});
  dispersionReceiptEvent(p,'Liquidación anticipada aplicada',`Total liquidado ${fmtMoney(total)} · Recibido ${fmtMoney(amount)}${excess>0?` · Excedente no aplicado ${fmtMoney(excess)}`:''}`);
  if(!dispersionCommitReceipt(tx))return false; patientTab='dispersion'; renderPatientDetail(); toast('Liquidación anticipada aplicada. Crédito cerrado.');
  return true;
}

dispersionApplyCapitalPrepayment:
function dispersionApplyCapitalPrepayment(p,amount,date,reference,method){
  if(!requireCapability('patientActions'))return false;
  if(!dispersionCanPrepayOrLiquidate(p)){
    toast('No es posible aplicar prepago a capital antes de la fecha habilitada por la configuración vigente.');
    return false;
  }
  const tx=dispersionBeginReceipt(p,amount,date,reference,method);if(!tx)return false;
  const terms=dispersionTerms(p);
  const rows=dispersionEnsureSchedule(p);
  let remaining=amount;
  let appliedToDues=0;
  let appliedToCapital=0;
  const dueRows=rows.filter(r=>['Vencido','Pendiente','Parcial'].includes(r.status)||(dispersionIsExtensionActiveRow(r)&&String(r.currentDueDate||r.dueDate)<=date)||dispersionIsAdjustedPrepayPayable(r)).sort((a,b)=>String(a.dueDate||'').localeCompare(String(b.dueDate||'')));
  dueRows.forEach(row=>{
    if(remaining<=0)return;
    const before=remaining;
    const result=dispersionApplyAmountToConcepts(row,remaining,date,reference,method);
    const applied=before-result.remaining;
    if(applied>0){
      row.paymentType='capital_prepay';
      row.status=row.pendingAmount<=0?'Pagado':dispersionDaysPastDue(row.currentDueDate||row.dueDate)>0?'Vencido':'Parcial';
      appliedToDues+=applied;
      remaining=result.remaining;
    }
  });

  const futureRowsForBalance=rows.filter(r=>r.type!=='Pago inicial requerido'&&!['Pagado','Pagado anticipado','Reducida por prepago','Liquidado anticipadamente','Cancelada por liquidación','Cancelado','Condonado'].includes(String(r.status||'')));
  const capitalBalanceBeforePrepayment=futureRowsForBalance.reduce((sum,row)=>sum+dispersionCapitalPendingForSettlement(row),0);
  const capitalPrepaymentAmount=Math.max(remaining,0);
  let capitalBalanceAfterPrepayment=capitalBalanceBeforePrepayment;

  if(capitalPrepaymentAmount>0){
    const futureRows=rows.filter(r=>r.type!=='Pago inicial requerido'&&['Programado','Ajustada por prepago'].includes(r.status)).sort((a,b)=>String(b.dueDate||'').localeCompare(String(a.dueDate||'')));
    for(const row of futureRows){
      if(remaining<=0)break;
      if(row.status==='Reducida por prepago')continue;
      const currentCapital=Math.max(dispersionNumber(row.currentCapital,row.capital),0);
      if(currentCapital<=0)continue;
      const applied=Math.min(remaining,currentCapital);
      row.originalCapital=dispersionNumber(row.originalCapital,currentCapital);
      row.originalPayment=dispersionNumber(row.originalPayment,row.payment);
      row.capitalPrepayReduction=dispersionNumber(row.capitalPrepayReduction,0)+applied;
      row.totalCapitalReducedByPrepayment=row.capitalPrepayReduction;
      row.prepaymentDate=date;
      row.prepaymentReference=reference;
      row.prepaymentMethod=method;
      row.paymentType='capital_prepay';
      row.prepaymentEffect='term_reduction';
      row.currentCapital=Math.max(currentCapital-applied,0);
      row.capital=row.currentCapital;
      row.capitalPending=row.currentCapital;
      row.payment=row.capital+dispersionNumber(row.interest,0)+dispersionNumber(row.interestIva,0);
      row.totalPayment=row.payment+dispersionNumber(row.moratory,0)+dispersionNumber(row.moratoryIva,0)+dispersionNumber(row.commission,0);
      row.pendingAmount=Math.max(row.totalPayment-dispersionNumber(row.paidAmount,0),0);
      if(row.currentCapital<=0){
        row.prepaymentFullyReduced=true;
        row.isClosed=true;
        row.interest=0; row.interestIva=0; row.capital=0; row.currentCapital=0; row.capitalPending=0; row.payment=0; row.totalPayment=0; row.pendingAmount=0;
        row.status='Reducida por prepago';
      }else{
        row.prepaymentFullyReduced=false;
        row.isClosed=false;
        row.status='Ajustada por prepago';
      }
      remaining-=applied;
      appliedToCapital+=applied;
    }
    capitalBalanceAfterPrepayment=Math.max(capitalBalanceBeforePrepayment-appliedToCapital,0);
  }

  p.paymentSchedule=dispersionNormalizePrepayFutureBalances(rows,terms);
  if(!Array.isArray(p.payments))p.payments=[];
  const reducedRows=p.paymentSchedule.filter(r=>r.status==='Reducida por prepago').length;
  const adjustedRows=p.paymentSchedule.filter(r=>r.status==='Ajustada por prepago').length;
  const prepayMove={amount,date,reference,method,target:'auto',paymentType:'capital_prepay',createdAt:new Date().toISOString(),appliedToDues,appliedToCapital,effect:'reduce_term',reducedRows,adjustedRows,unappliedAmount:remaining,capitalBalanceBeforePrepayment,capitalAppliedToPrepayment:appliedToCapital,capitalBalanceAfterPrepayment};
  prepayMove.movementLabel=dispersionPrepayMovementLabel(prepayMove);
  prepayMove.movementCopy=dispersionPrepayMovementCopy(prepayMove);
  p.payments.push(prepayMove);
  dispersionReceiptEvent(p,prepayMove.movementLabel,`Recibido ${fmtMoney(amount)} · Adeudos ${fmtMoney(appliedToDues)} · Capital ${fmtMoney(appliedToCapital)} · Saldo capital después ${fmtMoney(capitalBalanceAfterPrepayment)} · Efecto: reducción de plazo${remaining>0?` · Sobrante no aplicado ${fmtMoney(remaining)}`:''}`);
  if(!dispersionCommitReceipt(tx))return false; patientTab='dispersion'; renderPatientDetail();
  if(appliedToDues>0&&appliedToCapital>0)toast('Pago aplicado. Se cubrieron adeudos pendientes y el excedente se aplicó a capital para reducir plazo.');
  else if(appliedToDues>0&&appliedToCapital<=0)toast('Pago aplicado a adeudos pendientes. No hubo excedente para prepago a capital.');
  else if(appliedToDues<=0&&appliedToCapital>0)toast('Prepago a capital aplicado. El pago mensual se mantiene y el plazo se reduce.');
  else toast('No fue posible aplicar el pago.');
  return true;
}

dispersionApplyUpfrontOpeningFeePayment:
function dispersionApplyUpfrontOpeningFeePayment(p,amount,date,reference,method){
  if(!requireCapability('patientActions'))return false;
  const terms=dispersionTerms(p);
  if((terms.openingFeeMode||'upfront')!=='upfront'){
    toast('La comisión de este crédito está financiada; no se cobra upfront.');
    return false;
  }
  const pending=dispersionUpfrontOpeningFeePending(p,terms);
  if(pending<=0){toast('La comisión por apertura upfront ya está pagada.');return false;}
  if(!Number.isFinite(Number(amount))||Number(amount)<=0){toast('Captura un monto válido para aplicar el pago.');return false;}
  const tx=dispersionBeginReceipt(p,amount,date,reference,method);if(!tx)return false;
  const previouslyPaid=dispersionUpfrontOpeningFeePaidAmount(p,terms.openingFeeAmount);
  const applied=Math.min(roundToCents(amount),pending);
  const remaining=roundToCents(Math.max(amount-applied,0));
  p.application=p.application||{};
  p.offer=p.offer||{};
  p.application.openingFeeUpfrontPaid=applied>=pending;
  p.offer.openingFeeUpfrontPaid=p.application.openingFeeUpfrontPaid;
  p.application.openingFeeUpfrontPaidAmount=roundToCents(previouslyPaid+applied);
  p.offer.openingFeeUpfrontPaidAmount=p.application.openingFeeUpfrontPaidAmount;
  if(!Array.isArray(p.payments))p.payments=[];
  const movement={amount:applied,date,reference,method,target:'commission_upfront',paymentType:'commission_upfront',type:'commission_upfront',movementLabel:'Comisión por apertura upfront',movementCopy:`Comisión pagada ${fmtMoney(applied)}${remaining>0?` · Sobrante no aplicado ${fmtMoney(remaining)}`:''}`,createdAt:new Date().toISOString(),unappliedAmount:remaining};
  p.payments.push(movement);
  dispersionReceiptEvent(p,'Comisión por apertura upfront pagada',`${fmtMoney(applied)} · ${method} · ${reference}${remaining>0?` · Sobrante ${fmtMoney(remaining)}`:''}`);
  if(!dispersionCommitReceipt(tx))return false; patientTab='dispersion'; renderPatientDetail(); toast('Comisión por apertura upfront registrada');
  return true;
}

dispersionApplyPayment:
function dispersionApplyPayment(){
  if(!requireCapability('patientActions'))return false;
  const p=contractSelectedPatient(); if(!p)return;
  if(dispersionIsCreditLiquidated(p)){toast('Este crédito ya fue liquidado anticipadamente. No se pueden aplicar nuevos pagos.');return;}
  const amount=dispersionNumber(document.getElementById('dispersionPaymentAmount')?.value,0);
  if(!amount||amount<=0){toast('Captura un monto válido para aplicar el pago.');return;}
  const paymentType=(document.getElementById('dispersionPaymentType')?.value||'ordinary').trim();
  if(paymentType==='commission_upfront'){const date=document.getElementById('dispersionPaymentDate')?.value||dispersionDateOnly(new Date()); const reference=((document.getElementById('dispersionPaymentReference')?.value||'').trim()||''); const method=(document.getElementById('dispersionPaymentMethod')?.value||'SPEI').trim(); dispersionApplyUpfrontOpeningFeePayment(p,amount,date,reference,method); return;}
  if(paymentType==='capital_prepay'){const date=document.getElementById('dispersionPaymentDate')?.value||dispersionDateOnly(new Date()); const reference=((document.getElementById('dispersionPaymentReference')?.value||'').trim()||''); const method=(document.getElementById('dispersionPaymentMethod')?.value||'SPEI').trim(); dispersionApplyCapitalPrepayment(p,amount,date,reference,method); return;}
  if(paymentType==='early_liquidation'){const date=document.getElementById('dispersionPaymentDate')?.value||dispersionDateOnly(new Date()); const reference=((document.getElementById('dispersionPaymentReference')?.value||'').trim()||''); const method=(document.getElementById('dispersionPaymentMethod')?.value||'SPEI').trim(); dispersionApplyEarlySettlement(p,amount,date,reference,method); return;}
  const date=document.getElementById('dispersionPaymentDate')?.value||dispersionDateOnly(new Date());
  const reference=((document.getElementById('dispersionPaymentReference')?.value||'').trim()||'');
  const method=(document.getElementById('dispersionPaymentMethod')?.value||'SPEI').trim();
  const target=(document.getElementById('dispersionPaymentTarget')?.value||'auto').trim();
  const rows=dispersionBuildSchedule(p);
  let remaining=amount;
  let candidates=[];
  if(paymentType==='advance_installment'){
    const a=p.application||{};
    if(!(a.dispersionDate||a.disbursedAt||a.dispersedAt||a.amortizationStatus==='active')){toast('El pago anticipado solo está disponible cuando la tabla esté activa.');return;}
    if(target==='auto')candidates=rows.filter(r=>dispersionIsAdvancePayableRow(r)&&r.type!=='Pago inicial requerido');
    else candidates=rows.filter(r=>r.id===target&&dispersionIsAdvancePayableRow(r)&&r.type!=='Pago inicial requerido');
    if(!candidates.length){toast('No hay mensualidades futuras programadas disponibles para pago anticipado.');return;}
  }else{
    if(target==='auto'){
      candidates=rows.filter(r=>dispersionIsOrdinaryPayableRow(r));
    }else{
      const selected=rows.find(r=>r.id===target);
      if(selected&&dispersionIsAdvancePayableRow(selected)){toast('Para cubrir mensualidades futuras selecciona Pago anticipado de mensualidad.');return;}
      if(selected&&selected.status==='Ajustada por prepago'&&!dispersionIsAdjustedPrepayPayable(selected)){toast('Esta mensualidad fue ajustada por prepago, pero aún no es exigible. Para cubrirla antes de su fecha, selecciona Pago anticipado de mensualidad.');return;}
      if(selected&&!dispersionIsOrdinaryPayableRow(selected)){toast('Esta amortización no puede recibir pago ordinario.');return;}
      candidates=selected?[selected]:[];
    }
    if(!candidates.length){toast('No hay amortizaciones pendientes, parciales, vencidas o ajustadas exigibles para aplicar pago ordinario.');return;}
  }
  const tx=dispersionBeginReceipt(p,amount,date,reference,method);if(!tx)return false;
  for(const row of candidates){
    if(remaining<=0)break;
    if(dispersionIsClosedPaymentStatus(row.status))continue;
    if(paymentType==='ordinary'&&!dispersionIsOrdinaryPayableRow(row))continue;
    if(paymentType==='advance_installment'&&!dispersionIsAdvancePayableRow(row))continue;
    const pending=Math.max(dispersionNumber(row.pendingAmount,row.totalPayment),0);
    if(pending<=0)continue;
    const result=dispersionApplyAmountToConcepts(row,remaining,date,reference,method);
    row.paymentType=paymentType;
    if(paymentType==='advance_installment')row.status=row.pendingAmount<=0?'Pagado anticipado':'Parcial anticipado';
    remaining=result.remaining;
    if(target!=='auto')break;
  }
  p.paymentSchedule=rows;
  if(!Array.isArray(p.payments))p.payments=[];
  p.payments.push({amount,date,reference,method,target,paymentType,createdAt:new Date().toISOString(),unappliedAmount:remaining});
  dispersionReceiptEvent(p,paymentType==='advance_installment'?'Pago anticipado aplicado':'Pago aplicado',`${dispersionPaymentTypeLabel(paymentType)} · ${fmtMoney(amount)}${remaining>0?` · Sobrante no aplicado ${fmtMoney(remaining)}`:''}`);
  if(!dispersionCommitReceipt(tx))return false; patientTab='dispersion'; renderPatientDetail(); toast(paymentType==='advance_installment'?'Pago anticipado aplicado':'Pago aplicado');
}
